INSERT INTO sentences (id, language_id, text, reading_kana, level_id, source, published) VALUES
INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-dokoroka-1', 'sent-ex-dokoroka-1', 'en', 'Far from resting, I got busier.', 'authored'),
  ('st-ex-dokoroka-2', 'sent-ex-dokoroka-2', 'en', 'Far from getting cheaper, the price went up.', 'authored'),
  ('st-ex-dokoroka-3', 'sent-ex-dokoroka-3', 'en', 'Far from apologising, he was laughing.', 'authored'),
  ('st-ex-dokoroka-4', 'sent-ex-dokoroka-4', 'en', 'Not so much as a reply — there was no word at all.', 'authored'),
  ('st-ex-dokorodewanai-1', 'sent-ex-dokorodewanai-1', 'en', 'I am too busy for anything like a holiday.', 'authored'),
  ('st-ex-dokorodewanai-2', 'sent-ex-dokorodewanai-2', 'en', 'With the exam coming, this is no time for playing.', 'authored'),
  ('st-ex-dokorodewanai-3', 'sent-ex-dokorodewanai-3', 'en', 'I was ill; work was out of the question.', 'authored'),
  ('st-ex-dokorodewanai-4', 'sent-ex-dokorodewanai-4', 'en', 'I have no money, so shopping is out of the question.', 'authored'),
  ('st-ex-bakarika-1', 'sent-ex-bakarika-1', 'en', 'Not only did it rain, the wind got up as well.', 'authored'),
  ('st-ex-bakarika-2', 'sent-ex-bakarika-2', 'en', 'He is good not only at English but at cooking too.', 'authored'),
  ('st-ex-bakarika-3', 'sent-ex-bakarika-3', 'en', 'Not only is it expensive, it tastes bad as well.', 'authored'),
  ('st-ex-bakarika-4', 'sent-ex-bakarika-4', 'en', 'Not only was he late, he did not get in touch either.', 'authored'),
  ('st-ex-monodakara-1', 'sent-ex-monodakara-1', 'en', 'The train was late, and that is why I was late in.', 'authored'),
  ('st-ex-monodakara-2', 'sent-ex-monodakara-2', 'en', 'I was busy, and that is why I did not get in touch.', 'authored'),
  ('st-ex-monodakara-3', 'sent-ex-monodakara-3', 'en', 'It was cheap, and so I went and bought it.', 'authored'),
  ('st-ex-monodakara-4', 'sent-ex-monodakara-4', 'en', 'I had a headache, and that is why I stayed off.', 'authored'),
  ('st-ex-uede-1', 'sent-ex-uede-1', 'en', 'I will decide after giving it proper thought.', 'authored'),
  ('st-ex-uede-2', 'sent-ex-uede-2', 'en', 'I will reply after talking it over.', 'authored'),
  ('st-ex-uede-3', 'sent-ex-uede-3', 'en', 'Please ask your questions after hearing the explanation.', 'authored'),
  ('st-ex-uede-4', 'sent-ex-uede-4', 'en', 'I will report after the investigation.', 'authored'),
  ('st-ex-ueni-1', 'sent-ex-ueni-1', 'en', 'It is cheap, and good as well.', 'authored'),
  ('st-ex-ueni-2', 'sent-ex-ueni-2', 'en', 'He is kind, and interesting with it.', 'authored'),
  ('st-ex-ueni-3', 'sent-ex-ueni-3', 'en', 'It rained, and on top of that the wind was strong.', 'authored'),
  ('st-ex-ueni-4', 'sent-ex-ueni-4', 'en', 'I got lost, and on top of that I was rained on.', 'authored'),
  ('st-ex-sueni-1', 'sent-ex-sueni-1', 'en', 'After long thought, I decided.', 'authored'),
  ('st-ex-sueni-2', 'sent-ex-sueni-2', 'en', 'After talking it over, we decided to call it off.', 'authored'),
  ('st-ex-sueni-3', 'sent-ex-sueni-3', 'en', 'After all that effort, I succeeded.', 'authored'),
  ('st-ex-sueni-4', 'sent-ex-sueni-4', 'en', 'After a long argument, we reached a conclusion.', 'authored'),
  ('st-ex-ageku-1', 'sent-ex-ageku-1', 'en', 'After waiting a long time, I was turned down.', 'authored'),
  ('st-ex-ageku-2', 'sent-ex-ageku-2', 'en', 'After all that arguing, nothing was decided.', 'authored'),
  ('st-ex-ageku-3', 'sent-ex-ageku-3', 'en', 'After all that dithering, I did not buy it.', 'authored'),
  ('st-ex-ageku-4', 'sent-ex-ageku-4', 'en', 'After working long hours, he ended up ill.', 'authored'),
  ('st-ex-tsuideni-1', 'sent-ex-tsuideni-1', 'en', 'While I was out shopping I went to the bank.', 'authored'),
  ('st-ex-tsuideni-2', 'sent-ex-tsuideni-2', 'en', 'I will post the letter on my way to the station.', 'authored'),
  ('st-ex-tsuideni-3', 'sent-ex-tsuideni-3', 'en', 'While I was cleaning I tidied the room too.', 'authored'),
  ('st-ex-tsuideni-4', 'sent-ex-tsuideni-4', 'en', 'I took a photograph while I was out for a walk.', 'authored'),
  ('st-ex-yara-1', 'sent-ex-yara-1', 'en', 'What with homework and getting ready, I am busy.', 'authored'),
  ('st-ex-yara-2', 'sent-ex-yara-2', 'en', 'What with the rain and the wind, it was awful.', 'authored'),
  ('st-ex-yara-3', 'sent-ex-yara-3', 'en', 'There are books and notebooks and everything else lying about.', 'authored'),
  ('st-ex-yara-4', 'sent-ex-yara-4', 'en', 'What with the crying and the laughing, it was quite a business.', 'authored')
